validator:
function validate(input) {
  const [{ Numbers = [] }] = input;
  const seen = new Set();
  for (const [num, frequency] of Numbers) {
    if (num === null) return 'Every row needs a num.';
    if (seen.has(num)) return `num ${num} appears twice in Numbers.`;
    seen.add(num);
    if (frequency === null || frequency < 1) return `num ${num} needs a positive frequency.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const Numbers = [];
  if (size === 'small') {
    // A few distinct values from a small range, including negatives, with small frequencies so middles often split.
    const pool = [-2, -1, 0, 1, 2, 3, 4, 5, 6];
    for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
    const rows = pick(7);
    for (let i = 0; i < rows; i++) Numbers.push([pool[i], 1 + pick(4)]);
  } else {
    const used = new Set();
    while (Numbers.length < 1500) {
      const num = pick(20000) - 5000;
      if (used.has(num)) continue;
      used.add(num);
      Numbers.push([num, 1 + pick(rand() < 0.1 ? 500 : 20)]);
    }
  }
  return [{ Numbers }];
}
